import React, { useContext, useEffect, useState } from 'react';
import UrlApi from '../data/UrlApi';
import { useNavigate } from 'react-router-dom';
import { setToken } from '../utils/GenUtils';
import '../styles/login.css';
import { UrlContext } from './UrlContext';

const defaultData = { 
  emailId: '',
  password: '',
};

const Login = ({ setLogin }) => {
  const navigate = useNavigate();
  const urlConsumer = useContext(UrlContext);
  // const [emailId, setEmailId] = useState('');
  // const [password, setPassword] = useState('');
  const [userData, setUserData] = useState(defaultData);
  const [error, setError] = useState(null);

  useEffect(() => {
    sessionStorage.setItem("page", 0);
    sessionStorage.setItem("limit", 5);
    setLogin(true);
  }, []);

  const handleValues = (e) => {
    setUserData({
      ...userData,
      [e.target.name]: e.target.value,
    })
  }
  console.log(userData);

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      // Simulating an API request
      // const response = await fetch('your-auth-api-endpoint', {
      //   method: 'POST',
      //   headers: {
      //     'Content-Type': 'application/json',
      //   },
      //   body: JSON.stringify({ username, password }),
      // });
      // const data = { emailId, password };
      UrlApi.login(userData, (err, res) => {
        console.log("UrlApi.login::res");
        console.log(err);
        console.log(res);
        if (err) {
          setError(err.data.message);
          return;
        }
        urlConsumer.disableLoginError();
        setToken(res.data.accessToken);
        setLogin(false)
        navigate("/");
      })
    } catch (error) {
      console.error('Error during login:', error);
      setError('An error occurred during login');
    }
  };

  return (
    <div className="container">
      <form className="form">
        <h2>Login</h2>
        <input
          type="text"
          id="emailId"
          name="emailId"
          placeholder="Email id"
          autoComplete="off"
          value={userData.emailId}
          onChange={handleValues}
        />
        <input
          type="password"
          placeholder="Password"
          id="password"
          name="password"
          autoComplete="off"
          value={userData.password}
          onChange={handleValues}
        />
        <button onClick={handleLogin}>Login</button>
        {error && <div style={{ color: 'red' }}>{error}</div>}
      </form>
    </div>
  );
};

export default Login;
