
export const isLoggedIn = () => !!localStorage.getItem("token");
export const getToken = () => localStorage.getItem("token") ? localStorage.getItem("token") : null;
export const setToken = token => {
    localStorage.setItem("token", token)
}
export const removeToken = () => localStorage.removeItem("token")

export const trimDescription = (isSmallScreen, description) => {
  // Adjust the description length based on screen width
  const maxLength = isSmallScreen ? 40 : 70; // Example lengths, adjust as needed
  return description.length > maxLength
    ? description.slice(0, maxLength) + "..."
    : description;
};