import React from "react";
import {
  Button,
  TextField,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
} from "@mui/material";
import { AdapterMoment } from '@mui/x-date-pickers/AdapterMoment';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';
import { renderTimeViewClock } from '@mui/x-date-pickers/timeViewRenderers';
import moment from "moment";

export default function FormDialog(props) {
  let {
    modalOpen, handleModalClose, 
    originalUrl, urlName, expirationDate, mode, setExpirationDate, handleChange, onSubmit
  } = props;

  // const onSubmit = (urlDetails) => {
  //   const urlSaved = handleSubmitUrl(urlDetails);
  //   console.log("urlSaved");
  //   console.log(urlSaved);
  //   setModalOpen(false);
  // }

  const onModalClose = (e, reason) => {
    if (mode === "add") {
      if (originalUrl || urlName) {
        let shouldCloseDialog = window.confirm("Changes not saved, do you want to proceed ?");
        if (shouldCloseDialog) {
          props.closeWithoutSaving();
        }
      } else {
        handleModalClose(e, reason)
      }
    } else {
      // onSubmit();
      handleModalClose(e, reason)
    }
  }

  const clearClicked = (elem, e) => {
    console.log("ClearClicked");
    console.log(elem);
    console.log(e);
    setExpirationDate('')
  }

  return (
    <React.Fragment>
      <Dialog
        open={modalOpen}
        onClose={handleModalClose}
        disableEscapeKeyDown={false}
        // maxWidth="xl"
        fullScreen={true}
        PaperProps={{
          component: "form",
          elevation: 12,
          onSubmit: (event) => {
            event.preventDefault();
            const formData = new FormData(event.currentTarget);
            const formJson = Object.fromEntries(formData.entries());
            console.log("formJson");
            console.log(formJson);
            onSubmit(formJson);
            // props.handleModalClose();
          },
        }}
      >
        <DialogTitle>Short URL</DialogTitle>
        <DialogContent>
          <DialogContentText>
            Create a short url of your favorite / bookmarked url
          </DialogContentText>
          <TextField
            label="Original URL"
            fullWidth
            // error={originalUrlErr.error}
            // helperText={originalUrlErr.message}
            disabled={mode === "update"}
            name="originalUrl"
            type="url"
            placeholder="Enter a valid url starting with http or https"
            margin="normal"
            value={originalUrl}
            onChange={handleChange}
          />
          <TextField
            label="URL Name"
            fullWidth
            margin="normal"
            name="urlName"
            placeholder="Description of the URL"
            value={urlName}
            // error={urlNameErr.error}
            // helperText={urlNameErr.message}
            onChange={handleChange}
          />
          {mode === "update" ? (
            <LocalizationProvider dateAdapter={AdapterMoment}>
              <DateTimePicker
                label="Expiration Date"
                name="expirationDate"
                format="DD/MM/YYYY hh:mm a"
                value={moment(expirationDate)}
                showDaysOutsideCurrentMonth={true}
                // disablePast={true}
                slotProps={{
                  textField: {
                    fullWidth: true,
                    margin: "normal",
                    // error: expirationDateErr.error,
                    // helperText: expirationDateErr.message
                  },
                  field: { clearable: true, onClear: clearClicked },
                  actionBar: {
                    actions: ["clear"],
                  },
                }}
                onChange={(value, error) =>
                  handleChange(value, error, "expirationDate")
                }
                viewRenderers={{
                  hours: renderTimeViewClock,
                  minutes: renderTimeViewClock,
                  seconds: renderTimeViewClock,
                }}
              />
            </LocalizationProvider>
          ) : (
            <LocalizationProvider dateAdapter={AdapterMoment}>
              <DateTimePicker
                label="Expiration Date"
                name="expirationDate"
                format="DD/MM/YYYY hh:mm a"
                showDaysOutsideCurrentMonth={true}
                
                slotProps={{
                  textField: {
                    fullWidth: true,
                    margin: "normal",
                    // error: expirationDateErr.error,
                    // helperText: expirationDateErr.message
                  },
                  field: { clearable: true, onClear: clearClicked },
                  actionBar: {
                    actions: ["clear"],
                  },
                }}
                onChange={(value, error) =>
                  handleChange(value, error, "expirationDate")
                }
                viewRenderers={{
                  hours: renderTimeViewClock,
                  minutes: renderTimeViewClock,
                  seconds: renderTimeViewClock,
                }}
              />
            </LocalizationProvider>
          )}
          {/* <TextField
            label="Expiration Date"
            type="date"
            fullWidth
            margin="normal"
            //   InputLabelProps={{ shrink: true }}
            slotProps={{
              inputLabel: { shrink: true },
            }}
            name="expirationDate"
            value={expirationDate}
            onChange={handleChange}
          /> */}
        </DialogContent>
        <DialogActions>
          <Button onClick={onModalClose}>Cancel</Button>
          <Button type="submit">Submit</Button>
        </DialogActions>
      </Dialog>
    </React.Fragment>
  );
}
