import axios from "axios";
import { 
  LOGIN_ROUTE,
  LOGOUT_ROUTE,
  LIST_URL_ROUTE,
  INSERT_URL_ROUTE
} from '../config/routeConfig';
import {getToken} from '../utils/GenUtils';

export default class UrlApi {

  static addUrl(data, callback) {
    axios.post(INSERT_URL_ROUTE,
    { ...data },
    {
      headers: {
        'Authorization': getToken()
      }
    })
      .then(res => {
        console.log("Response::");
        console.log(res);
        callback(res);
      })
      .catch(err => {
        console.log("Error::addUrl");
        console.log(err);
        callback(err);
      })
  }

  static login(data, callback) {
    axios.post(LOGIN_ROUTE,
    {
      ...data
    })
    .then(res => {
      console.log("Response::");
      console.log(res);
      callback(null, res.data);
    })
    .catch(err => {
      console.log("Error::login");
      console.log(err);
      callback(err.response, null);
    })
  }

  static logout(callback) {
    axios.get(LOGOUT_ROUTE, {
      headers: {
        'Authorization': getToken()
      }
    })
    .then(res => {
      console.log("Logout Response::");
      console.log(res);
      callback(null, res.data);
    })
    .catch(err => {
      console.log("Error::logout");
      console.log(err);
      callback(err.response, null);
    })
  }

  static listUrl(data, callback) {

    axios.post(LIST_URL_ROUTE,      
        {
          ...data
        }, {
          headers: {
            'Authorization': getToken()
          }
        })
      .then(res => {
        console.log("Response::");
        console.log(res);
        callback(res);
      })
      .catch(err => {
        console.log("Error::listUrl");
        console.log(err);
        callback(err);
      })


  }
  
}
